<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { AlertTriangle, Calculator, ChevronDown, Plus } from 'lucide-vue-next'
import { pricingApi, type PricingRecord } from '../api/pricing'
import type { OrderItemPayload } from '../api/orders'
import { formatMoney, formatMoneyInput, parseMoneyInput, type CurrencyUnit } from '../utils/currency'
const props=defineProps<{services:any[];materials:any[];currencyUnit:CurrencyUnit;initial?:any}>();const emit=defineEmits<{configured:[payload:OrderItemPayload];cancel:[]}>()
const serviceId=ref('');const values=ref<Record<string,string>>({});const quantity=ref('');const unit=ref('unit');const notes=ref('');const overrideText=ref('');const manualTexts=ref<Record<string,string>>({});const pricing=ref<PricingRecord|null>(null);const error=ref('');const calculating=ref(false)
const service=computed(()=>props.services.find(s=>s.id===serviceId.value));const activeParams=computed(()=>service.value?.parameters?.filter((p:any)=>p.active!==false)||[]);const manualComponents=computed(()=>service.value?.components?.filter((c:any)=>c.enabled&&c.type==='manual')||[]);const manualCosts=ref<Record<string,number>>({})
function initialize(){const initial=props.initial;serviceId.value=initial?.serviceId||props.services.find(s=>s.active)?.id||'';values.value={};if(initial?.resolvedParametersJson){try{for(const p of JSON.parse(initial.resolvedParametersJson)){values.value[p.key]=p.value}}catch{}};quantity.value=initial?.quantity||'';unit.value=initial?.quantityUnit||'unit';notes.value=initial?.notes||'';overrideText.value='';manualTexts.value={};pricing.value=null}
watch(()=>[props.initial,props.services],initialize,{immediate:true});watch(serviceId,()=>{values.value={};pricing.value=null})
function setValue(key:string,event:Event){values.value[key]=(event.target as HTMLInputElement).value}
function updateMoneyText(event:Event, key:string){const text=(event.target as HTMLInputElement).value;if(key==='override'){overrideText.value=text;const parsed=parseMoneyInput(text,props.currencyUnit);if(parsed!==null)overrideText.value=formatMoneyInput(parsed,props.currencyUnit);return}manualTexts.value[key]=text;const parsed=parseMoneyInput(text,props.currencyUnit);if(parsed!==null)manualCosts.value[key]=parsed}
async function calculate(){error.value='';calculating.value=true;try{const override=overrideText.value.trim()?parseMoneyInput(overrideText.value,props.currencyUnit):null;if(overrideText.value.trim()&&override===null)throw new Error('Enter a valid selling price');pricing.value=await pricingApi.calculate({serviceId:serviceId.value,parameters:values.value,manualCosts:manualCosts.value,sellingPriceOverrideRial:override})}catch(e){error.value=String(e).replace(/^Error:\s*/,'')}finally{calculating.value=false}}
function save(){if(!pricing.value){error.value='Calculate the item before adding it';return}const override=overrideText.value.trim()?parseMoneyInput(overrideText.value,props.currencyUnit):null;emit('configured',{serviceId:serviceId.value,parameters:{...values.value},manualCosts:{...manualCosts.value},sellingPriceOverrideRial:override,quantity:quantity.value,quantityUnit:unit.value,notes:notes.value})}
</script>
<template><section class="item-configurator panel"><header class="configurator-heading"><div><p class="section-kicker">{{ initial?'Reconfigure item':'Add service item' }}</p><h2>Configure service</h2><p class="panel-subtitle">Pricing is calculated by the persisted service definition.</p></div><button class="button button-secondary" @click="emit('cancel')">Cancel</button></header><div class="configurator-form"><label>Service<span class="select-control"><select v-model="serviceId"><option value="" disabled>Select active service</option><option v-for="item in services.filter((s:any)=>s.active||s.id===serviceId)" :key="item.id" :value="item.id">{{ item.name }}<template v-if="item.code"> · {{ item.code }}</template></option></select><ChevronDown class="select-chevron" :size="14"/></span></label><div v-if="activeParams.length" class="parameter-grid"><label v-for="parameter in activeParams" :key="parameter.id">{{ parameter.label }}<select v-if="parameter.type==='choice'" :value="values[parameter.key]||parameter.defaultValue" @change="setValue(parameter.key,$event)"><option value="">Select…</option><option v-for="option in parameter.options" :key="option">{{ option }}</option></select><input v-else-if="parameter.type==='boolean'" type="checkbox" :checked="values[parameter.key]==='true'" @change="values[parameter.key]=($event.target as HTMLInputElement).checked?'true':'false'"><select v-else-if="parameter.type==='material-reference'" :value="values[parameter.key]" @change="setValue(parameter.key,$event)"><option value="">Select material…</option><option v-for="material in materials.filter((m:any)=>m.active)" :key="material.id" :value="material.id">{{ material.name }}</option></select><input v-else :value="values[parameter.key]" :type="parameter.type==='integer'?'number':'text'" :placeholder="parameter.defaultValue||parameter.type" @input="setValue(parameter.key,$event)"><small v-if="parameter.unit">{{ parameter.unit }}</small></label></div><p v-else class="configurator-empty">This service has no dynamic parameters.</p><div class="form-grid"><label>Item quantity<input v-model="quantity" placeholder="Defaults from quantity parameter"/></label><label>Unit<input v-model="unit" placeholder="unit"/></label></div><div v-if="manualComponents.length" class="manual-costs"><label v-for="component in manualComponents" :key="component.id">{{ component.name }}<input :value="manualTexts[component.id]||''" @input="updateMoneyText($event,component.id)" :placeholder="`Amount in ${currencyUnit}`"/></label></div><label>Notes<textarea v-model="notes" rows="2" placeholder="Item-specific notes"/></label><div class="form-grid"><label>Selling price override<input :value="overrideText" inputmode="decimal" @input="updateMoneyText($event,'override')" :placeholder="`Optional ${currencyUnit} price`"/></label><button class="button button-secondary calculate-button" type="button" :disabled="calculating||!serviceId" @click="calculate"><Calculator :size="15"/>{{ calculating?'Calculating…':'Calculate price' }}</button></div></div><div v-if="error" class="configurator-error"><AlertTriangle :size="15"/>{{ error }}</div><div v-if="pricing" class="pricing-preview"><div class="pricing-preview-head"><strong>Accepted pricing preview</strong><span v-if="pricing.belowCost" class="below-cost"><AlertTriangle :size="14"/>Below cost</span></div><div class="pricing-summary"><span>Estimated cost<strong>{{ formatMoney(pricing.estimatedCostRial,currencyUnit) }}</strong></span><span>Suggested price<strong>{{ formatMoney(pricing.suggestedSellingPriceRial,currencyUnit) }}</strong></span><span>Effective price<strong>{{ formatMoney(pricing.effectiveSellingPriceRial,currencyUnit) }}</strong></span><span>Profit / margin<strong>{{ formatMoney(pricing.profitRial,currencyUnit) }} · {{ pricing.marginPercentage }}%</strong></span></div><div class="breakdown-list"><div v-for="component in pricing.components" :key="component.id"><span>{{ component.name }}</span><strong>{{ component.enabled?formatMoney(component.amountRial,currencyUnit):'Disabled' }}</strong></div></div><button class="button button-primary" type="button" @click="save"><Plus :size="15"/>{{ initial?'Replace item':'Add item to order' }}</button></div></section></template>
